import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleSheetNotFound {
    public void handle(@Parameter SheetNotFoundException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.NOT_FOUND));
    }
}
package net.officefloor.hq.app.sheet;

/** A sheet load with a blank or over-long id, or no signed-in user. */
public class InvalidSheetException extends Exception {
    public InvalidSheetException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.sheet;

import org.springframework.web.bind.annotation.PathVariable;

/** Fails when the sheet id has never been loaded. */
public class LoadSheet {
    public void load(@PathVariable("sheetId") String sheetId, SheetRepository repository)
            throws SheetNotFoundException {
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.exists(id)) {
            throw new SheetNotFoundException(id);
        }
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class RespondWithSheet {
    public void respond(@PathVariable("sheetId") String sheetId, SheetRepository repository,
            ObjectResponse<SheetResponse> response) throws SheetNotFoundException {
        String id = sheetId.trim();
        var today = repository.today(id);
        if (today == null) {
            throw new SheetNotFoundException(id);
        }
        response.send(new SheetResponse(id, today.toString(), repository.archived(id)));
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Archive the sheet when a steward asks and it is not archived yet, recording SHEET_ARCHIVED. */
public class SaveArchive {
    public void save(@PathVariable("sheetId") String sheetId, @Val ArchiveRequest request, SheetRepository sheets,
            RoleRepository roles, Audit audit) throws InvalidSheetException {
        String sheet = sheetId.trim();
        if (!Role.STEWARD.equals(roles.of(sheet, request.user()))) {
            throw new InvalidSheetException("Only a steward can archive the sheet.");
        }
        if (!sheets.archive(sheet)) {
            throw new InvalidSheetException("This sheet is already archived.");
        }
        audit.record("SHEET_ARCHIVED sheet=" + sheet + " by=" + request.user());
    }
}
package net.officefloor.hq.app.sheet;

import org.springframework.web.bind.annotation.PathVariable;
import net.officefloor.plugin.variable.Val;

public class SaveSheet {
    public void save(@PathVariable("sheetId") String sheetId, @Val SheetRequest request,
            SheetRepository repository) {
        repository.ensure(sheetId.trim(), request.user().trim());
    }
}
