  const byId = new Map(people.map((p) => [p.id, p]));
  return live(claims, people, late.today)
    .filter((c) => overdue(c, late.today))
    .map((c) => claimDue(c, rateOn(rates, gradeOn(byId.get(c.personId), c.date), c.date), floor, late));
}

/** What the late charge follows: the sheet's late percent by date (two decimals; a claim gains the one in force
 *  on each 30-day boundary past its due-by) and its today; and
 *  how a claim's live figures round: the policy date (the policy-date setting, else the sheet's today; '' while
 *  loading) and the dates of the sheet's numbered claims (a correction rounds by the claim it corrects). */
export type Late = { pct: DatedValue; today: string; policy: string; numbered: Map<string, string> };

/** Whether a claim's live figures round half up: it (a correction: the claim it corrects) is dated before the
 *  policy date; else they round half to even. */
export function roundsUp(claim: Claim, late: Late): boolean {
  const date = claim.corrects !== null ? late.numbered.get(claim.corrects) ?? claim.date : claim.date;
  return late.policy !== '' && date < late.policy;
}

/** A claim's due: the one fixed when it was settled (its late charge frozen in), else the greater of the sheet's floor
 *  in force on its date and its figure — the one its person's last statement bound it to, n/a included (not while it
 *  is PENDING: then it is live), else live on its amount at the rate — with the late charge on that figure added. A
 *  correction (a negative amount) has no floor and no late charge. */
export function claimDue(claim: Claim, rate: string | undefined, floor: DatedValue, late: Late): string {
  if (claim.settledDue !== null) return claim.settledDue;
  const correction = toCents(claim.amount) < 0n;
  const live = dueOn(claim.amount, rate, roundsUp(claim, late));
  const bound = claim.status === 'PENDING' || !claim.stated ? null : claim.statedDue ?? 'n/a';
  const figure = bound ?? live;
  if (correction || figure === 'n/a') return figure;
  return floored(fromCents(toCents(figure) + toCents(lateCharge(claim, figure, late))), floor(claim.date));
}

const DAY_MS = 24 * 60 * 60 * 1000;

/** The late charge on a claim whose figure is `figure`: for each full 30 days the claim is overdue (past its due-by, on
 *  the sheet's today), the late percent in force on that boundary date (its due-by plus 30, 60, 90 ... days) of it,
 *  rounded like the claim's due, the charges added up (a boundary whose percent is 0.00 adds nothing); 0.00 when not
 *  overdue, or a correction (a negative amount). */
export function lateCharge(claim: Claim, figure: string, late: Late): string {
  if (!overdue(claim, late.today) || toCents(claim.amount) < 0n) return '0.00';
  const from = Date.parse(`${dueBy(claim)}T00:00:00Z`);
  const days = Math.round((Date.parse(`${late.today}T00:00:00Z`) - from) / DAY_MS);
  let total = 0n;
  for (let n = 1; n <= Math.floor(days / 30); n++) {
    const pct = late.pct(new Date(from + n * 30 * DAY_MS).toISOString().slice(0, 10));
    if (toCents(pct) !== 0n) total += toCents(dueOn(figure, pct, roundsUp(claim, late)));
  }
  return fromCents(total);
}

/** A due raised to the floor when below it; 'n/a' stays 'n/a'. */
export function floored(due: string, floor: string): string {
  return due === 'n/a' || toCents(due) >= toCents(floor) ? due : fromCents(toCents(floor));
}

import { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useClaims } from '../claims/claims';
import type { Late } from '../rates/rates';
import { useSheetToday } from '../sheet/sheet';

/** The sheet's settings: the clerk limit with two decimals ('' when there is none) and the floor with two
 *  decimals (a claim's live due is at least it), and the terms in days (a claim's due-by is its date plus them), and
 *  the late percent with two decimals (an overdue claim gains, of its figure, the one in force on each full 30-day boundary past its due-by), and the
 *  policy date (yyyy-mm-dd; '' when blank: the sheet's today) a claim's live figures round by, and the period numbering from (yyyy-mm-dd; '' when off: on or after it, by
 *  the sheet's today, a claim opened is numbered within its period), and each grade's own terms in days ('' when the
 *  grade has none: it uses the sheet's terms), and the cap with two decimals ('' when there is none: a person's
 *  due-total is at most it), and the proof threshold with two decimals ('' when there is none: a claim whose due is
 *  above the one in force on its date cannot be settled or approved without a proof). A claim's due-by is fixed when it is created. Each is the value in force on the sheet's
 *  today; `dated` holds every value recorded for the settings that carry a figure, by key (clerk-limit, floor, terms,
 *  terms-A/B/C, late-pct, cap, proof-threshold), oldest from-date first. `perms` is the permission matrix (not dated): for
 *  each action the roles that may take it, comma separated ('' when blank: the standing rule). `graceDays` is the grace days (not dated; '' when off): when the sheet's
 *  today is changed, each open period whose to-date plus them is before the new today is closed. */
export type Settings = { clerkLimit: string; floor: string; terms: string; latePct: string; policyDate: string;
  periodNumberingFrom: string; gradeTerms: Record<string, string>; cap: string; proofThreshold?: string; dated?: Record<string, Dated[]>;
  perms?: Record<string, string>; graceDays?: string };

/** A dated setting's value ('' when blank) in force from its from-date (yyyy-mm-dd). */
export type Dated = { from: string; value: string };

/** A dated figure as it applies to a date (yyyy-mm-dd): the value in force on it. */
export type DatedValue = (date: string) => string;

/** The value of a dated setting in force on a date: the one with the latest from-date on or before it, else the
 *  sheet's starting value. */
export function valueOn(values: Dated[] | undefined, start: string, date: string): string {
  let found: Dated | undefined;
  for (const v of values ?? []) {
    if (v.from <= date && (!found || found.from < v.from)) found = v;
  }
  return found ? found.value : start;
}

/** The actions the permission matrix covers, in order. */
export const PERM_ACTIONS = ['open', 'settle', 'void', 'reassign', 'close', 'reopen'] as const;

/** The grades that may have terms of their own. */
export const GRADES = ['A', 'B', 'C'] as const;

export const settingsKey = (sheetId: string) => ['sheet', sheetId, 'settings'] as const;

/** The floor a sheet starts with. */
export const DEFAULT_FLOOR = '1.00';

/** The terms a sheet starts with, in days. */
export const DEFAULT_TERMS = '14';

/** The late percent a sheet starts with. */
export const DEFAULT_LATE_PCT = '0.00';

/** The sheet's settings as they are now. */
export function useSettings(sheetId: string) {
  return useQuery({
    queryKey: settingsKey(sheetId),
    queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`),
  });
}

/** The sheet's floor by date: a claim's live due is at least the one in force on its date (the starting floor
 *  while the settings load). */
export function useFloor(sheetId: string): DatedValue {
  const dated = useSettings(sheetId).data?.dated?.floor;
  return useMemo(() => (date: string) => valueOn(dated, DEFAULT_FLOOR, date), [dated]);
}

/** The sheet's cap in force ('' when there is none, or while the settings load). */
export function useCap(sheetId: string): string {
  return useSettings(sheetId).data?.cap ?? '';
}

/** The sheet's terms in force, in days (the starting terms while the settings load). */
export function useTerms(sheetId: string): number {
  return Number(useSettings(sheetId).data?.terms ?? DEFAULT_TERMS);
}

/** What the late charge follows now: the late percent by date (a claim gains the one in force on its date) and the sheet's today; and how claims round:
 *  the policy date in force (blank: the sheet's today) and the dates of the sheet's numbered claims. */
export function useLate(sheetId: string): Late {
  const settings = useSettings(sheetId).data;
  const today = useSheetToday(sheetId);
  const claims = useClaims(sheetId).data;
  const numbered = useMemo(
    () => new Map((claims ?? []).filter((c) => c.number !== null).map((c) => [c.number as string, c.date])),
    [claims],
  );
  const dated = settings?.dated?.['late-pct'];
  const pct = useMemo(() => (date: string) => valueOn(dated, DEFAULT_LATE_PCT, date), [dated]);
  return { pct, today,
    policy: settings?.policyDate || today, numbered };
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A sheet: its id, its today (ISO yyyy-mm-dd) and whether it is archived (every change refused). */
export type Sheet = { id: string; today: string; archived: boolean };

export const sheetKey = (sheetId: string) => ['sheet', sheetId, 'meta'] as const;

export function useSheet(sheetId: string) {
  return useQuery({
    queryKey: sheetKey(sheetId),
    queryFn: () => getJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}`),
  });
}

/**
 * The sheet's today — the date every date-dependent decision and every default date on the sheet
 * uses. Never read the real clock (`new Date()`) for these; use this instead. '' while loading.
 */
export function useSheetToday(sheetId: string): string {
  return useSheet(sheetId).data?.today ?? '';
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx response: its status and the text the server sent with it. */
export class HttpError extends Error {
  constructor(
    message: string,
    readonly status: number,
    readonly body: string,
  ) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status, await res.text());
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

